// Immediate alert when user manually changes rate on an item row
frappe.ui.form.on('Sales Invoice Item', {
	rate(frm, cdt, cdn) {
		const row = locals[cdt][cdn];
		if (!row.item_code || !row.warehouse || row.is_free_item) return;

		frappe.call({
			method: 'frappe.client.get_value',
			args: {
				doctype: 'Bin',
				filters: { item_code: row.item_code, warehouse: row.warehouse },
				fieldname: 'valuation_rate'
			},
			callback(r) {
				if (!r.message) return;
				const val_rate = flt(r.message.valuation_rate);
				if (val_rate > 0 && flt(row.rate) < val_rate) {
					frappe.show_alert({
						message: __('Row {0} ({1}): Rate {2} is below valuation rate {3}', [
							row.idx,
							row.item_name,
							format_currency(row.rate, frm.doc.currency),
							format_currency(val_rate, frm.doc.currency)
						]),
						indicator: 'orange'
					}, 8);
				}
			}
		});
	}
});

// Collect below-cost warnings during validate, display them after save
// (showing during validate causes Frappe's post-save msgprint to clear the body)
frappe.ui.form.on('Sales Invoice', {
	validate(frm) {
		const warnings = [];
		(frm.doc.items || []).forEach(row => {
			const val_rate = flt(row.incoming_rate);
			if (!row.is_free_item && val_rate > 0 && flt(row.rate) < val_rate) {
				warnings.push(
					`<b>Row ${row.idx} — ${row.item_name}</b><br>` +
					`Selling rate: ${format_currency(row.rate, frm.doc.currency)} | ` +
					`Valuation rate: ${format_currency(val_rate, frm.doc.currency)}`
				);
			}
		});
		frm.__below_cost_warnings = warnings;
	},
	after_save(frm) {
		const warnings = frm.__below_cost_warnings;
		if (!warnings || !warnings.length) return;
		frm.__below_cost_warnings = null;
		frappe.msgprint({
			title: __('Selling Below Cost'),
			message:
				__('The following items are priced below their valuation rate. You may still save, but please verify this is intentional before proceeding.') +
				'<br><br>' +
				warnings.join('<br><br>'),
			indicator: 'orange'
		});
	}
});
